def cells(x,y,items,w):
    b=''
    for t in items:
        b+=f'<rect x="{x}" y="{y}" width="{w}" height="20" fill="#fff" stroke="#111"/>'+T(x+w/2,y+14,t,11,'middle',700); x+=w
    return b
